import java.util.*;

class Solution {
    public List<String> trendingTags(String[] words, int k) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String w : words) cnt.put(w, cnt.getOrDefault(w, 0) + 1);
        // top of heap = worst tag: lower count, or same count and alphabetically larger
        PriorityQueue<String> heap = new PriorityQueue<>((a, b) ->
            cnt.get(a).equals(cnt.get(b)) ? b.compareTo(a) : cnt.get(a) - cnt.get(b));
        for (String w : cnt.keySet()) {
            heap.offer(w);
            if (heap.size() > k) heap.poll();
        }
        List<String> res = new ArrayList<>();
        while (!heap.isEmpty()) res.add(heap.poll());
        Collections.reverse(res);   // best first
        return res;
    }
}

