function trendingTags(words, k) {
  const c = new Map(); for (const w of words) c.set(w, (c.get(w) || 0) + 1);
  return [...c.keys()].sort((a, b) => c.get(b) - c.get(a) || (a < b ? -1 : a > b ? 1 : 0)).slice(0, k);
}
